ALTER POLICY "billing terms read" ON public.visit_billing_terms USING (public.has_any_role(auth.uid(),ARRAY['finanzas','luis','administrador']::public.app_role[]) OR public.is_ops(auth.uid()) OR EXISTS(SELECT 1 FROM public.visits v WHERE v.id=visit_id AND v.staff_id IN (SELECT public.my_staff_ids())) OR EXISTS(SELECT 1 FROM public.visit_participants p WHERE p.visit_id=visit_billing_terms.visit_id AND p.staff_id IN (SELECT public.my_staff_ids()) AND p.active));
CREATE OR REPLACE FUNCTION public.field_billing_balance(_visit text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE total numeric;paid numeric;reported numeric;BEGIN
IF NOT (public.has_any_role(auth.uid(),ARRAY['finanzas','luis','administrador']::public.app_role[]) OR public.is_ops(auth.uid()) OR EXISTS(SELECT 1 FROM public.visits v WHERE v.id=_visit AND v.staff_id IN(SELECT public.my_staff_ids())) OR EXISTS(SELECT 1 FROM public.visit_participants p WHERE p.visit_id=_visit AND p.staff_id IN(SELECT public.my_staff_ids()) AND p.active)) THEN RAISE EXCEPTION 'Sin acceso financiero a esa visita'; END IF;
SELECT base_amount+extras-discount INTO total FROM public.visit_billing_terms WHERE visit_id=_visit;
SELECT coalesce(sum((data->>'amount')::numeric) FILTER(WHERE status='verificado'),0),coalesce(sum((data->>'amount')::numeric) FILTER(WHERE status='informado'),0) INTO paid,reported FROM public.records WHERE kind='cobro_campo' AND ref_id=_visit;
RETURN jsonb_build_object('authorized',total,'verified',paid,'reported',reported,'balance',CASE WHEN total IS NULL THEN NULL ELSE greatest(0,total-paid) END,'availableToReport',CASE WHEN total IS NULL THEN NULL ELSE greatest(0,total-paid-reported) END);END $$;
REVOKE ALL ON FUNCTION public.field_billing_balance(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.field_billing_balance(text) TO authenticated,service_role;